# -*- coding: utf-8 -*-
# (speaker, italian, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
M, N, C, F, G, R, GI = "Matteo", "Nora", "Chiara", "Filippo", "Graziella", "Renzo", "Giulia"
D = [
("#", "Scena 1 — Lunedì 10 marzo, ore 7.30. Il bar sotto casa di Matteo, Oltrarno.", "장면 1 — 3월 10일 월요일 오전 7시 30분. 올트라르노, 마테오의 집 아래 바."),
(None, "Bancone di marmo, odore di caffè e di cornetti. Matteo ha il casco della Vespa appoggiato accanto alla tazzina. Sul telefono, una notifica: «Filo Rosso — Corsini Scandicci: le mani ci sono, la voce non ancora».", "대리석 카운터, 커피와 코르네토 냄새. 마테오가 베스파 헬멧을 커피잔 옆에 내려놓았다. 휴대폰에 알림이 떠 있다. '필로 로소 — 코르시니 스칸디치: 손은 있다, 목소리는 아직'."),
(M, "(legge sottovoce) «Le mani ci sono. La voce, non ancora.» Ecco. È uscito.", "(작게 읽으며) '손은 있다. 목소리는, 아직.' 나왔네."),
(None, "Il telefono vibra. È Nora.", "휴대폰이 진동한다. 노라다."),
(N, "Hai visto? L'ha pubblicato alle sette in punto. Federica non dorme mai.", "봤어? 7시 정각에 올렸더라. 페데리카는 잠도 안 자나 봐."),
(M, "L'ho visto. Sono al secondo paragrafo e non so se ridere o piangere.", "봤어. 지금 두 번째 문단인데 웃어야 할지 울어야 할지 모르겠어."),
(N, "Leggimelo. Io l'ho letto di corsa, al semaforo.", "읽어 줘. 난 신호 대기하면서 후다닥 읽었거든."),
(M, "«Il bordo dipinto a mano è il più bello che si sia visto quest'anno a Milano. Il cuoio di Santa Croce profuma di bottega.» Fin qui, bene.", "'손으로 칠한 가장자리는 올해 밀라노에서 본 것 중 가장 아름답다. 산타크로체의 가죽에서는 공방 냄새가 난다.' 여기까진 좋아."),
(N, "Fin qui benissimo. E poi?", "여기까진 아주 좋지. 그다음은?"),
(M, "«Ma le forme ricordano troppo da vicino quelle delle grandi maison per cui il laboratorio lavora da trent'anni. Sono cugine ben educate, non ancora figlie.»", "'하지만 형태는 이 공방이 30년째 일해 온 대형 명품 브랜드들의 가방을 너무 가까이 닮았다. 예의 바른 사촌일 뿐, 아직 딸은 아니다.'"),
(N, "Ahi. Questa è la frase che leggeranno tutti.", "아이고. 다들 그 문장만 읽겠네."),
(M, "Cugine ben educate. Mia sorella questa non la digerisce.", "예의 바른 사촌이라. 우리 누나는 이거 못 삼켜."),
(N, "E tuo fratello?", "형은?"),
(M, "Mio fratello leggerà «grandi maison» e penserà subito al contratto con Parigi.", "형은 '대형 명품 브랜드'만 읽고 바로 파리 계약부터 떠올릴 거야."),
(N, "Per l'articolo sette?", "7조 때문에?"),
(M, "Esatto. Federica non ha fatto nomi, ma a Parigi sanno leggere tra le righe.", "맞아. 페데리카가 이름은 안 댔지만 파리 사람들은 행간을 읽을 줄 알거든."),
(N, "Senti, Matteo. Dal punto di vista della comunicazione la vedo così: è una buona recensione con una frase cattiva dentro.", "있잖아, 마테오. 홍보 쪽에서 보면 이래. 나쁜 문장 하나가 들어간 좋은 리뷰야."),
(M, "Benché la frase sia cattiva, il resto è un regalo. Lo so. Ma noi, con la frase cattiva, che cosa facciamo?", "문장이 고약하긴 해도 나머진 선물이지. 알아. 그런데 우린 그 고약한 문장을 어떻게 하지?"),
(N, "Niente, per ora. A un giornalista non si risponde con un post arrabbiato. Mai.", "지금은 아무것도. 기자한테 화난 게시물로 답하면 안 돼. 절대."),
(M, "E con un post gentile?", "친절한 게시물로는?"),
(N, "Nemmeno. Si risponde con il lavoro. Fra un mese, quando avremo qualcosa di nuovo da far vedere.", "그것도 안 돼. 일로 답하는 거야. 한 달 뒤, 새로 보여 줄 게 생겼을 때."),
(M, "(sospira) Va bene. Allora vado in laboratorio prima che lo legga Chiara.", "(한숨 쉬며) 알았어. 그럼 키아라가 읽기 전에 공방에 갈게."),
(N, "Troppo tardi. Giulia l'ha già girato nel gruppo di famiglia alle sette e cinque.", "늦었어. 줄리아가 7시 5분에 벌써 가족 단톡방에 돌렸어."),
(None, "Matteo apre il gruppo «Corsini a tavola». Quattordici messaggi. L'ultimo, di Chiara, è un punto. Soltanto un punto.", "마테오가 '식탁의 코르시니' 단톡방을 연다. 메시지 열네 개. 마지막은 키아라가 보낸 마침표 하나. 딱 마침표 하나."),
(M, "Un punto. Mia sorella ha risposto con un punto.", "마침표. 누나가 마침표 하나로 답했어."),
(N, "E che vuol dire, un punto?", "마침표는 무슨 뜻인데?"),
(M, "Vuol dire che prendo la Vespa. Subito.", "베스파 타라는 뜻이야. 지금 당장."),

("#", "Scena 2 — Ore 8.40. Il laboratorio, il tavolo di Chiara.", "장면 2 — 오전 8시 40분. 공방, 키아라의 작업대."),
(None, "Chiara è seduta al suo tavolo, il cappotto ancora addosso. Davanti a lei, le dodici borse del campionario in fila. Matteo entra con il casco in mano.", "키아라가 외투도 벗지 않은 채 작업대에 앉아 있다. 앞에는 샘플 가방 열두 개가 줄지어 있다. 마테오가 헬멧을 손에 들고 들어온다."),
(C, "Non dire niente. So già che cosa vuoi dire.", "아무 말 하지 마. 무슨 말 하려는지 이미 알아."),
(M, "Volevo dire buongiorno.", "좋은 아침이라고 하려던 건데."),
(C, "Buongiorno. «Cugine ben educate, non ancora figlie.» Bella frase, eh? Se la sarà preparata per una settimana.", "좋은 아침. '예의 바른 사촌일 뿐, 아직 딸은 아니다.' 멋진 문장이지? 일주일은 다듬었겠지."),
(M, "Chiara, il resto dell'articolo è bellissimo. Parla del bordo, del cuoio, delle mani di Renzo.", "누나, 기사 나머지는 정말 좋아. 가장자리, 가죽, 렌초의 손 얘기를 하잖아."),
(C, "Parla di tutto tranne che di me. Le mani sono di Renzo, il cuoio è di Bini, il bordo è una tecnica di cent'anni. E le forme, le uniche cose mie, ricordano le borse degli altri.", "나만 빼고 다 얘기하지. 손은 렌초 거, 가죽은 비니 거, 가장자리는 백 년 된 기술이고. 그리고 형태, 유일하게 내 것인 그게 남의 가방을 닮았대."),
(M, "Non ha scritto «copiate». Ha scritto «ricordano».", "'베꼈다'고 쓴 게 아니잖아. '닮았다'고 썼지."),
(C, "Matteo, io quel verbo lo conosco. Me l'hanno detto anche a Polimoda, vent'anni fa. «Brava, ma ricorda qualcun altro.» Non sono mica una principiante.", "마테오, 난 그 동사 잘 알아. 20년 전 폴리모다에서도 들었어. '잘했어, 근데 누구를 닮았네.' 나 초보 아니거든."),
(None, "Filippo entra di passo svelto, il telefono in mano.", "필리포가 휴대폰을 손에 든 채 성큼성큼 들어온다."),
(F, "L'avete letto. Bene. Allora parliamo di una cosa sola: «le grandi maison per cui il laboratorio lavora».", "읽었구나. 좋아. 그럼 딱 한 가지만 얘기하자. '이 공방이 일해 온 대형 명품 브랜드들'."),
(M, "Lo sapevo.", "그럴 줄 알았어."),
(F, "Non ha fatto nomi, d'accordo. Ma Hélène legge «Filo Rosso» tutte le mattine. Me l'ha detto lei a Pitti.", "이름은 안 댔지, 그래. 그런데 엘렌은 매일 아침 '필로 로소'를 읽어. 피티에서 본인이 그랬어."),
(C, "Quindi il problema è Parigi. Non che la mia collezione sia senza voce.", "그러니까 문제는 파리라는 거네. 내 컬렉션에 목소리가 없다는 게 아니라."),
(F, "Il problema sono tutte e due le cose. Ma una sola può costarci il contratto.", "둘 다 문제야. 하지만 계약을 날릴 수 있는 건 하나뿐이지."),
(M, "L'articolo sette dice: niente modelli confondibili con quelli della Maison. Nessuno dei dodici lo è. Li abbiamo controllati insieme, uno per uno.", "7조는 메종 모델과 혼동될 만한 모델은 안 된다는 거야. 열두 개 중에 그런 건 하나도 없어. 같이 하나하나 확인했잖아."),
(F, "Li abbiamo controllati noi. Una giornalista ha appena scritto il contrario a trentamila lettori.", "우리가 확인했지. 기자 한 명이 방금 독자 3만 명한테 반대로 썼고."),
(C, "Ha scritto che «ricordano». Non che sono uguali. Sei tu che mi hai sempre detto di leggere i contratti con attenzione.", "'닮았다'고 썼어. 똑같다고 쓴 게 아니라. 계약서는 꼼꼼히 읽으라고 늘 말한 건 오빠잖아."),
(F, "(sospira) Hai ragione. Scusa. Chiamo Hélène io, prima che chiami lei.", "(한숨 쉬며) 네 말이 맞아. 미안. 엘렌이 전화하기 전에 내가 먼저 할게."),
(None, "Entra Graziella con l'articolo stampato e piegato in quattro. Dietro di lei, Renzo.", "그라치엘라가 네 번 접은 기사 인쇄본을 들고 들어온다. 뒤에 렌초가 있다."),
(G, "L'ho fatto stampare in ufficio. Al telefono le parole sono troppo piccole. Buongiorno a tutti.", "사무실에서 뽑아 왔어. 휴대폰으로는 글씨가 너무 작아서. 다들 좋은 아침."),
(M, "Buongiorno, mamma. L'hai letto tutto?", "좋은 아침이에요, 엄마. 다 읽으셨어요?"),
(G, "Due volte. Rileggendolo ad alta voce, in macchina, l'ho capito meglio. Ve lo dico come ve lo direbbe vostro padre: è un buon articolo.", "두 번. 차 안에서 소리 내어 다시 읽으니까 더 잘 이해되더라. 너희 아버지가 했을 법한 말로 할게. 좋은 기사야."),
(C, "Mamma...", "엄마…"),
(G, "Fammi finire, Chiara. È un buon articolo con una frase vera dentro. Le frasi false si dimenticano. Quelle vere fanno male, ma servono.", "끝까지 들어, 키아라. 진짜 문장 하나가 들어 있는 좋은 기사야. 거짓 문장은 잊히지. 진짜 문장은 아프지만 쓸모가 있어."),
(C, "Quindi anche tu pensi che le mie borse non abbiano voce.", "그럼 엄마도 내 가방에 목소리가 없다고 생각하는 거네요."),
(G, "Penso che sia la prima collezione. Tuo nonno ci ha messo dieci anni a fare una borsa che la gente riconoscesse da lontano.", "첫 컬렉션이라고 생각해. 네 할아버지는 사람들이 멀리서도 알아보는 가방 하나를 만드는 데 10년이 걸리셨어."),
(R, "Dodici, signora. Dal cinquantotto al settanta. Me lo raccontava lui.", "12년입니다, 사모님. 58년부터 70년까지요. 그분이 직접 해 주신 얘기예요."),
(G, "Dodici. Grazie, Renzo. Lei se lo ricorda meglio di me.", "12년. 고마워요, 렌초. 나보다 더 잘 기억하시네요."),
(R, "Io c'ero solo dal sessantasei. Ma la borsa del settanta l'ho vista nascere.", "저는 66년부터였을 뿐인걸요. 하지만 70년 가방은 태어나는 걸 봤죠."),
(C, "E com'era?", "어땠어?"),
(R, "Brutta, le prime tre volte. Poi un giorno il signor Ugo ha tagliato via tutto quello che somigliava ad altri. È rimasta una borsa sola. La sua.", "처음 세 번은 못생겼지. 그러다 어느 날 우고 사장님이 남을 닮은 건 전부 잘라 내셨어. 가방 하나만 남았지. 그분 가방."),
(C, "E quanto ci ha messo, a tagliare via tutto?", "그럼 다 잘라 내는 데는 얼마나 걸렸어?"),
(R, "Una notte. Dodici anni per arrivarci, una notte per farlo.", "하룻밤. 거기까지 가는 데 12년, 해치우는 데 하룻밤."),
(G, "Vedi, Chiara? Non è una condanna. È un indirizzo.", "봤지, 키아라? 판결이 아니야. 가야 할 방향이지."),
(C, "Un indirizzo che mi ha dato una sconosciuta davanti a trentamila persone.", "모르는 사람이 3만 명 앞에서 알려 준 방향이네요."),
(G, "Anche tuo padre odiava i giornalisti. Poi li invitava a cena.", "네 아버지도 기자를 싫어했어. 그러고 나선 저녁에 초대했지."),
(M, "Federica a cena? Mamma, non esageriamo.", "페데리카를 저녁에요? 엄마, 너무 나가지 마세요."),
(G, "Ho detto «poi». Non «domani».", "'그러고 나선'이라고 했지, '내일'이라고는 안 했다."),
(F, "Va bene. Io vado a chiamare Parigi. Matteo, vieni con me?", "좋아. 난 파리에 전화하러 갈게. 마테오, 같이 갈래?"),
(M, "Vengo. Chiara, ne parliamo dopo?", "갈게. 누나, 나중에 얘기할까?"),
(C, "(senza alzare gli occhi) Dopo.", "(눈도 들지 않고) 나중에."),

("#", "Scena 3 — Ore 15. Lo stesso tavolo, coperto di fogli strappati.", "장면 3 — 오후 3시. 같은 작업대, 찢긴 종이로 뒤덮여 있다."),
(None, "Chiara disegna, strappa, ricomincia. Renzo, al tavolo accanto, ritaglia scarti di cuoio. Fuori piove.", "키아라가 그리고, 찢고, 다시 시작한다. 옆 작업대의 렌초는 가죽 자투리를 자르고 있다. 밖에는 비가 온다."),
(R, "Hai strappato tre fogli in un'ora. Di questo passo, stasera finisci il quaderno.", "한 시간에 세 장을 찢었네. 이대로면 저녁엔 스케치북이 동나겠다."),
(C, "Li strappo perché sono cugine, Renzo. Tutte cugine.", "사촌들이라서 찢는 거야, 렌초. 전부 사촌."),
(R, "Allora non strapparli. Mettili da parte. Anche le cugine servono, ai matrimoni.", "그럼 찢지 마. 따로 둬. 사촌도 결혼식에선 쓸모가 있잖아."),
(C, "(quasi ride) Tu hai sempre una risposta.", "(웃을 뻔하며) 렌초는 늘 대답이 있네."),
(R, "Ho settantadue anni. A quest'età le risposte si accumulano, come i ritagli. E alle critiche ci si abitua. Ai complimenti, mai.", "일흔둘이니까. 이 나이엔 대답이 쌓여, 자투리처럼. 그리고 비판엔 익숙해지는데 칭찬엔 절대 안 익숙해져."),
(None, "Entra Giulia, lo zaino ancora in spalla, i capelli bagnati.", "줄리아가 책가방을 멘 채, 젖은 머리로 들어온다."),
(GI, "Zia! Ho visto. Ho visto anche che hai risposto con un punto. Sei arrabbiatissima.", "고모! 봤어요. 고모가 마침표로 답한 것도 봤어요. 엄청 화났네요."),
(C, "Non sono arrabbiata. Sono...", "화난 거 아니야. 그냥…"),
(GI, "Offesa?", "기분 상했어요?"),
(C, "Ferita. È diverso.", "상처받았어. 그건 달라."),
(GI, "Nora dice di non rispondere sui social. Però io avevo un'idea. Posso?", "노라가 SNS에서 대응하지 말래요. 그런데 저한테 아이디어가 있어요. 말해도 돼요?"),
(C, "Se è un'idea da sedici anni, sì.", "열여섯 살다운 아이디어면, 돼."),
(GI, "Invece di rispondere all'articolo, facciamo vedere questo. Tu che disegni, strappi e ricominci. Senza parole. Solo le mani e i fogli.", "기사에 답하는 대신 이걸 보여 주는 거예요. 고모가 그리고, 찢고, 다시 시작하는 거. 말 없이. 손이랑 종이만."),
(C, "Vuoi pubblicare i miei fogli strappati?", "내 찢은 종이들을 올리겠다고?"),
(GI, "Sì. Perché sono veri. La giornalista ha scritto che manca la voce. La voce è questa: una che non si arrende.", "네. 진짜니까요. 기자는 목소리가 없다고 썼잖아요. 목소리는 이거예요. 포기하지 않는 사람."),
(R, "(annuisce) La ragazza ha ragione. Ma prima di farlo vedere, bisogna avere qualcosa in mano.", "(고개를 끄덕이며) 아이 말이 맞아. 하지만 보여 주기 전에 손에 뭔가 쥐고 있어야 해."),
(C, "E che cosa, Renzo?", "뭘, 렌초?"),
(R, "Una borsa sola. Non dodici. Una che non somiglia a niente.", "가방 하나. 열두 개 말고. 아무것도 닮지 않은 하나."),
(GI, "E se non viene?", "안 나오면요?"),
(R, "Viene. Le borse sono come i gatti: se le guardi troppo, scappano. Tu disegna e non guardarla.", "나와. 가방은 고양이 같아서 너무 쳐다보면 도망가. 그냥 그리고, 쳐다보지 마."),
(C, "Bel consiglio, per una designer.", "디자이너한테 참 좋은 조언이네."),
(GI, "Io lo trovo bellissimo. Me lo scrivo.", "난 너무 좋은데요. 적어 둘래요."),
(None, "Entra Matteo, i capelli schiacciati dal casco, l'aria stanca.", "헬멧에 눌린 머리로 마테오가 지친 얼굴로 들어온다."),
(M, "Ho parlato con Parigi. Cioè, Filippo ha parlato con Parigi. Io ho ascoltato.", "파리랑 통화했어. 아니, 형이 통화했고 난 들었어."),
(C, "E allora?", "그래서?"),
(M, "Hélène l'aveva già letto. Ha detto che «ricordano» non era un problema giuridico. Che il problema sarebbe stato se un giorno ci fosse stato scritto «uguali».", "엘렌은 이미 읽었더라. '닮았다'는 법적인 문제가 아니라고 했어. 언젠가 '똑같다'고 쓰였다면 문제가 됐을 거래."),
(C, "Quindi siamo salvi.", "그럼 우린 무사하네."),
(M, "Siamo salvi se la prossima collezione non ricorda nessuno. Parole sue, più o meno.", "다음 컬렉션이 아무도 닮지 않으면 무사한 거래. 대충 그런 말이었어."),
(C, "Allora ha detto la stessa cosa di Federica. Con un contratto in mano.", "그럼 페데리카랑 같은 말을 한 거네. 계약서를 들고서."),
(M, "Più o meno. Chiara... da dove cominci?", "대충. 누나… 어디서부터 시작할 거야?"),
(C, "(prende un foglio nuovo) Da quello che vedo io e nessun altro. La sera, dal mio terrazzo, le colline dietro Scandicci. Una linea sola.", "(새 종이를 집으며) 나만 보고 다른 사람은 못 보는 것부터. 저녁에 우리 집 테라스에서 보는 스칸디치 뒤 언덕. 선 하나."),
(GI, "Posso filmarti mentre la disegni?", "그리는 거 찍어도 돼요?"),
(C, "Solo le mani. Come Renzo.", "손만. 렌초처럼."),
(None, "Chiara traccia una lunga curva, poi una seconda, più morbida. Renzo prende un ritaglio di cuoio e lo piega lungo la linea.", "키아라가 긴 곡선을 하나 긋고, 이어서 더 부드러운 선을 하나 더 긋는다. 렌초가 가죽 자투리를 집어 그 선을 따라 접는다."),
(R, "Così, la piega. Senza cucitura sopra. Il signor Ugo l'avrebbe chiamata «la collina».", "이렇게, 접는 거야. 위에 박음질 없이. 우고 사장님이라면 '언덕'이라고 부르셨을 거다."),
(C, "«La Collina». (scrive il nome in alto sul foglio) Va bene. Questa è la prima che è figlia.", "'라 콜리나.' (종이 위쪽에 이름을 쓴다) 좋아. 이게 처음으로 딸인 가방이야."),

("#", "Scena 4 — Ore 20. L'ufficio export, al primo piano.", "장면 4 — 오후 8시. 2층 수출팀 사무실."),
(None, "Il laboratorio è vuoto. Matteo è ancora al computer. Arriva una mail da un indirizzo giapponese: «Kenji Watanabe — Tokyo».", "공방은 비었다. 마테오는 아직 컴퓨터 앞이다. 일본 주소에서 메일이 한 통 온다. '와타나베 겐지 — 도쿄'."),
(M, "(legge) «Gentile signor Corsini, mi chiamo Kenji Watanabe. Ho un negozio a Tokyo, a Daikanyama. Ho vissuto dieci anni a Roma.»", "(읽는다) '코르시니 씨께. 저는 와타나베 겐지라고 합니다. 도쿄 다이칸야마에서 가게를 하고 있습니다. 로마에서 10년을 살았습니다.'"),
(F, "(dalla porta) Ancora qui? Sono le otto.", "(문간에서) 아직 여기 있어? 8시야."),
(M, "Vieni a sentire. Una mail dal Giappone.", "와서 들어 봐. 일본에서 온 메일이야."),
(F, "Dal Giappone? Chi ci conosce, in Giappone?", "일본? 일본에서 누가 우릴 알아?"),
(M, "Uno che ha letto l'articolo di stamattina. Ascolta: «Ho letto l'articolo di Federica Sala. Mi ha colpito una frase: le mani ci sono, la voce non ancora.»", "오늘 아침 기사를 읽은 사람. 들어 봐. '페데리카 살라의 기사를 읽었습니다. 한 문장이 마음에 남았습니다. 손은 있다, 목소리는 아직.'"),
(F, "Ecco. Anche in Giappone leggono la frase cattiva.", "봐. 일본에서도 그 나쁜 문장을 읽는다고."),
(M, "Aspetta. «In trent'anni di mestiere ho imparato che la voce si trova. Le mani, invece, o ci sono o non ci sono. Sarei lieto di ricevere il vostro catalogo.»", "잠깐. '30년 동안 이 일을 하며 배운 건, 목소리는 찾을 수 있다는 것입니다. 하지만 손은 있거나 없거나 둘 중 하나입니다. 카탈로그를 받아 볼 수 있다면 기쁘겠습니다.'"),
(F, "(si siede sul bordo della scrivania) Davvero ha scritto così?", "(책상 모서리에 걸터앉으며) 정말 그렇게 썼어?"),
(M, "Davvero. E chiude così: «Sarò in Italia in primavera. Con i migliori saluti, Kenji Watanabe.»", "정말. 그리고 이렇게 끝내. '봄에 이탈리아에 갑니다. 안부를 전하며, 와타나베 겐지.'"),
(F, "Tommaso Guidi in Giappone fa il quaranta per cento. Me l'hai detto tu, a Pitti.", "토마소 귀디는 일본에서 매출의 40%를 낸다며. 피티에서 네가 그랬잖아."),
(M, "Lo so. E adesso c'è uno che ci scrive per primo.", "알아. 그리고 이번엔 상대가 먼저 연락해 왔어."),
(F, "«Chi chiama per primo ha bisogno.» Lo diceva il babbo.", "'먼저 전화하는 쪽이 아쉬운 쪽이다.' 아버지가 그러셨지."),
(M, "Stavolta ha chiamato lui, non noi. Rispondo stasera?", "이번엔 우리가 아니라 그쪽이 먼저 했어. 오늘 밤에 답할까?"),
(F, "Rispondi domani mattina, con calma. E mandagli il catalogo nuovo, quello con le mani di Renzo in copertina. Non quello vecchio.", "내일 아침에 차분히 답해. 그리고 새 카탈로그를 보내. 렌초 손이 표지에 있는 거. 옛날 거 말고."),
(M, "E la frase cattiva? La citiamo?", "그 나쁜 문장은? 인용해?"),
(F, "(sorride per la prima volta in tutta la giornata) No. Citiamo quella buona: «il bordo dipinto a mano più bello dell'anno». Le frasi vere, a volte, sono due.", "(하루 중 처음으로 웃으며) 아니. 좋은 걸 인용해. '올해 가장 아름다운 손 칠 가장자리.' 진짜 문장이 가끔은 두 개야."),
(M, "E Chiara oggi ne ha scritta una terza. «La Collina».", "그리고 누나가 오늘 세 번째 문장을 썼어. '라 콜리나.'"),
(F, "La Collina? Che cos'è?", "라 콜리나? 그게 뭔데?"),
(M, "Una borsa. Domani te la fa vedere lei. Io non te la racconto: è sua.", "가방. 내일 누나가 직접 보여 줄 거야. 내가 설명하진 않을게. 누나 거니까."),
(F, "Chiara stamattina non mi ha nemmeno guardato.", "키아라는 오늘 아침에 나를 쳐다보지도 않았어."),
(M, "Stamattina tu le hai parlato di Parigi prima che di lei.", "형이 오늘 아침에 누나 얘기보다 파리 얘기를 먼저 했잖아."),
(F, "(pausa) Hai ragione. Domani le porto il caffè. Quello del bar, non quello della macchinetta.", "(잠시) 네 말이 맞다. 내일 커피 갖다줘야겠다. 자판기 거 말고 바에서."),
(M, "Due zuccheri. Se ne sbagli uno, ricominci da capo.", "설탕 두 개. 하나라도 틀리면 처음부터 다시야."),
(F, "Due zuccheri. Me lo ricordo da quando aveva dodici anni.", "설탕 두 개. 걔 열두 살 때부터 기억해."),
(M, "Allora ricordatelo anche domani.", "그럼 내일도 기억해."),
(None, "Filippo esce. Matteo scrive su un post-it «Watanabe — Tokyo» e lo attacca allo schermo, accanto a quello giallo con scritto «Kim — Seul».", "필리포가 나간다. 마테오가 포스트잇에 '와타나베 — 도쿄'라고 써서 '김 — 서울'이라고 적힌 노란 포스트잇 옆, 모니터에 붙인다."),
(M, "(tra sé) Seul e Tokyo. Due città, due post-it. E una borsa che si chiama «La Collina».", "(혼잣말로) 서울과 도쿄. 도시 두 곳, 포스트잇 두 장. 그리고 '라 콜리나'라는 이름의 가방 하나."),
]

